import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.DTdEDYjJ.js";const m=JSON.parse('{"title":"运行与数据","description":"了解本机与自建节点的区别、Bot 的执行资源、应用登录与数据保存方式。","frontmatter":{"title":"运行与数据","description":"了解本机与自建节点的区别、Bot 的执行资源、应用登录与数据保存方式。"},"headers":[],"relativePath":"guide/runtime-and-data.md","filePath":"guide/runtime-and-data.md"}'),d={name:"guide/runtime-and-data.md"};function n(i,t,h,p,l,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="运行与数据" tabindex="-1">运行与数据 <a class="header-anchor" href="#运行与数据" aria-label="Permalink to &quot;运行与数据&quot;">​</a></h1><p>OpenBot 可以从自己的 Mac 开始。需要远端执行时，再连接自己的 Linux Node。本页集中说明运行条件；产品首页介绍使用场景，安装步骤见<a href="/openbot/guide/quickstart.html">快速开始</a>，各端交付范围见<a href="/openbot/guide/status.html">支持与验证</a>。</p><h2 id="模型、执行器和设备分别选择" tabindex="-1">模型、执行器和设备分别选择 <a class="header-anchor" href="#模型、执行器和设备分别选择" aria-label="Permalink to &quot;模型、执行器和设备分别选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选择</th><th>配置方式</th></tr></thead><tbody><tr><td>模型</td><td>连接兼容 API，逐 Bot 选择模型；账号、额度与服务费用由模型服务商管理</td></tr><tr><td>执行器</td><td>默认 DSH，也可显式选择 Pi、兼容循环，或绑定已安装、已登录的受支持 CLI / ACP 执行器</td></tr><tr><td>运行设备</td><td>Mac 本机，或显式连接自己的 Linux / Docker Node</td></tr><tr><td>界面细节</td><td>默认保留对话与必要进度；工具记录按偏好展开，审批和停止仍可使用</td></tr></tbody></table><p>本机执行器使用其所在机器的登录环境，接入成功不等于将订阅搬到云端。远程浏览器任务使用 Node 自己的 API、模型与 Harness 配置，不继承 Mac 的执行器绑定或订阅。配置方法分别见<a href="/openbot/guide/models.html">模型与连接</a>、<a href="/openbot/guide/harness.html">Harness</a>和<a href="/openbot/deployment/overview.html">运行环境</a>。</p><h2 id="bot-常驻与屏幕资源" tabindex="-1">Bot 常驻与屏幕资源 <a class="header-anchor" href="#bot-常驻与屏幕资源" aria-label="Permalink to &quot;Bot 常驻与屏幕资源&quot;">​</a></h2><p>Bot 身份、记忆和任务记录持续保存，执行资源按任务需要申请。新建 Bot 不等于启动一个独立浏览器或容器；未获屏幕操作权限的 Bot 不能自行开启屏幕。</p><p>自建 Node 默认最多运行两个活跃浏览器，超出名额的屏幕申请等待，超时会明确失败。不在查看、无任务占用且未受人工接管保护的空闲屏幕可回收；有效人工接管期间保留。实际限制以节点配置为准；独立的浏览器资料与正在运行的屏幕是两个对象。</p><p>工作屏幕是 Chromium 浏览器环境，不代表完整 Mac、Windows 或 Linux 桌面。查看、审批、接管、交还与停止的行为见<a href="/openbot/guide/computer-use.html">浏览器工作屏幕</a>。</p><h2 id="关闭应用或断开连接" tabindex="-1">关闭应用或断开连接 <a class="header-anchor" href="#关闭应用或断开连接" aria-label="Permalink to &quot;关闭应用或断开连接&quot;">​</a></h2><p>本机任务依赖本机应用和设备持续运行。退出应用会停止本机执行，仅关闭 Mac 窗口不等于退出；笔记本休眠也不能当作继续执行的保证。</p><p>远程任务依赖节点和控制租约。客户端断连或节点重启后，任务可能中断，不保证自动继续。未完成任务保留明确状态，避免静默重放已经产生副作用的操作；恢复前应核对实际结果，再明确交办下一步。</p><p>常开设备的部署方法见<a href="/openbot/deployment/self-host.html">自建 Node</a>，设备连接、HTTPS 和局域网条件见<a href="/openbot/deployment/network.html">网络连接</a>。当前没有官方托管购买入口。</p><h2 id="登录与授权保存在什么地方" tabindex="-1">登录与授权保存在什么地方 <a class="header-anchor" href="#登录与授权保存在什么地方" aria-label="Permalink to &quot;登录与授权保存在什么地方&quot;">​</a></h2><p>浏览器资料可保留网站允许持久保存的登录状态。验证码、过期登录和网站限制仍需本人处理；OpenBot 不保证托管所有账号或永久保持登录。</p><p>GitHub 应用授权可由自己的 Node 加密保存凭据，再按主 Bot 与已开放的只读动作分配访问能力。它解决的是 Bot 使用 GitHub 的授权，不是用 GitHub 登录 OpenBot；本次已验收动作范围、撤销和续期边界见<a href="/openbot/guide/app-authorizations.html">自托管应用授权</a>。</p><p>本机资料、模型服务商和浏览器访问是不同的数据边界。选择远程节点后，节点使用自己的配置、凭据和持久状态，不会因为本机已登录就自动同步。备份和迁移应遵循<a href="/openbot/reference/configuration.html">配置参考</a>，不要将凭据或浏览器资料提交到源码仓库。</p><h2 id="官网体验与实际应用" tabindex="-1">官网体验与实际应用 <a class="header-anchor" href="#官网体验与实际应用" aria-label="Permalink to &quot;官网体验与实际应用&quot;">​</a></h2><p>首页提供真实 App 浏览器界面的交互预览，使用合成 Bot 与示例对话。输入只存在于当前演示会话，不连接模型、真实账号、本机执行器或云节点；重置会清除本次预览修改。</p><p>闲置 20 秒且页面和预览均可见时可自动演示，手动操作立即暂停；可关闭自动演示并保留偏好。编辑过的示例保持手动，只有明确重置才允许恢复自动演示；重置仍保留已关闭的偏好。它用来体验界面，不是一次真实任务执行证明。</p><p>官网、预览界面、仓库源码和安装包分别发布。Mac 试点 DMG 的下载需要主仓权限，手机与云端的验证记录见<a href="/openbot/guide/status.html">支持范围</a>。 <a href="/openbot/guide/platforms.html">平台与下载</a></p>',21)])])}const c=a(d,[["render",n]]);export{m as __pageData,c as default};
